-color-primary-element); outline-offset: 2px; }.metrics-cards,.metrics-insights { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin-bottom: 20px; }.metrics-insights { grid-template-columns: 1fr 2fr; }.metrics-card, .metrics-panel { background: var(--color-main-background); border: 1px solid var(--color-border); border-radius: var(--border-radius-large); padding: 18px; }.metrics-card { display: flex; flex-direction: column; gap: 7px; }.metrics-card span { color: var(--color-text-maxcontrast); }.metrics-card strong { font-size: 1.7rem; }.metrics-card small, .metrics-panel small { color: var(--color-text-maxcontrast); }.metrics-panel { margin-top: 20px; overflow-x: auto; }.metrics-insights .metrics-panel { margin-top: 0; }.metrics-panel h2 { margin: 0 0 14px; font-size: 1.15rem; }.token-split { text-align:center }.split-chart { width:116px;height:116px;border-radius:50%;margin:auto;background:conic-gradient(var(--color-primary-element) 0 var(--input),var(--color-success) var(--input) 100%);display:grid;place-items:center }.split-chart span { width:76px;height:76px;border-radius:50%;background:var(--color-main-background);display:grid;place-items:center;font-weight:700;font-size:.8rem }.chart-legend { display:grid;gap:5px;text-align:left;margin-top:14px;font-size:.85rem }.chart-legend i { display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px }.input-dot { background:var(--color-primary-element) }.output-dot { background:var(--color-success) }.model-bars { display:grid;gap:9px }.model-bar { display:grid;grid-template-columns:minmax(100px,1fr) 2fr auto;gap:9px;align-items:center;font-size:.85rem }.model-bar span { overflow:hidden;text-overflow:ellipsis;white-space:nowrap }.model-bar div { background:var(--color-background-hover);height:9px;border-radius:9px;overflow:hidden }.model-bar i { display:block;background:var(--color-primary-element);height:100%;border-radius:inherit } table { width:100%; border-collapse: collapse; } th, td { padding: 9px 8px; text-align: left; border-bottom: 1px solid var(--color-border); white-space: nowrap; } th { color: var(--color-text-maxcontrast); font-size: .85rem; }.mono { font-family: var(--font-face-monospace); }.metrics-empty, .metrics-loading, .metrics-error { color: var(--color-text-maxcontrast); }.metrics-error { display:flex; align-items:center; justify-content:space-between; gap:12px; background:var(--color-error-hover); border-radius:var(--border-radius-element); color:var(--color-error); padding:12px; }.metrics-retry { flex-shrink:0; border:1px solid var(--color-border); border-radius:var(--border-radius-element); padding:6px 10px; background:var(--color-main-background); color:var(--color-main-text); cursor:pointer; }.metrics-retry:hover { background:var(--color-background-hover); }.daily-list { display: grid; gap: 8px; }.daily-row { display: grid; grid-template-columns: 100px 1fr 90px; align-items: center; gap: 12px; font-size: .9rem; }.daily-row time { color: var(--color-text-maxcontrast); }.daily-row strong { text-align: right; }.daily-bar { height: 10px; background: var(--color-background-hover); border-radius: 8px; overflow: hidden; }.daily-bar span { display: block; height: 100%; min-width: 2px; background: var(--color-primary-element); border-radius: inherit; } @media (max-width: 760px) { .metrics-view { padding: 20px 12px; } .page-header { align-items: start; flex-direction: column; } .metrics-cards { grid-template-columns: repeat(2, minmax(0, 1fr)); }.metrics-insights { grid-template-columns:1fr; } }\n"],"sourceRoot":""}]);
